const INHERITING_NULL_PATHS = new Set([
  'delivery.enabled',
  'delivery.recipients',
  'display.columns',
  'limits.maxRows',
  'limits.timeoutMs',
]);

const MISSING = Symbol('missing');

function isRecord(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function copyValue(value) {
  if (Array.isArray(value)) {
    return value.map(copyValue);
  }

  if (isRecord(value)) {
    const copy = {};
    for (const key of Object.keys(value)) {
      defineValue(copy, key, copyValue(value[key]));
    }
    return copy;
  }

  return value;
}

function defineValue(object, key, value) {
  // Defining the property avoids treating a JSON field named "__proto__"
  // as a prototype setter.
  Object.defineProperty(object, key, {
    value,
    enumerable: true,
    configurable: true,
    writable: true,
  });
}

function resolveValue(path, values) {
  let selected = MISSING;

  for (const value of values) {
    if (value === undefined) continue;
    if (value === null && INHERITING_NULL_PATHS.has(path)) continue;
    selected = value;
    break;
  }

  if (selected === MISSING) return MISSING;

  if (!isRecord(selected)) return copyValue(selected);

  const keys = new Set();
  for (const value of values) {
    if (!isRecord(value)) continue;
    for (const key of Object.keys(value)) keys.add(key);
  }

  const result = {};
  for (const key of keys) {
    const childValues = values.map((value) =>
      isRecord(value) && Object.prototype.hasOwnProperty.call(value, key)
        ? value[key]
        : undefined,
    );
    const childPath = path ? `${path}.${key}` : key;
    const child = resolveValue(childPath, childValues);
    if (child !== MISSING) defineValue(result, key, child);
  }

  return result;
}

/**
 * Resolve report settings from lowest to highest priority layers.
 *
 * @param {object|undefined} defaults
 * @param {object|undefined} workspace
 * @param {object|undefined} request
 * @returns {object}
 */
export function resolveReportSettings(defaults, workspace, request) {
  const layers = [request, workspace, defaults].map((layer) =>
    isRecord(layer) ? layer : {},
  );
  const result = resolveValue('', layers);
  return result === MISSING ? {} : result;
}

const inheritNull = new Set([
  ['delivery', 'enabled'], ['delivery', 'recipients'], ['display', 'columns'],
  ['limits', 'maxRows'], ['limits', 'timeoutMs'],
].map(path => JSON.stringify(path)));
const record = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const clone = value => {
  if (Array.isArray(value)) return value.map(clone);
  if (record(value)) return Object.fromEntries(Object.entries(value).map(([k, v]) => [k, clone(v)]));
  return value;
};

export function resolveReportSettings(defaults, workspace, request) {
  function merge(layers, path) {
    const keys = new Set(layers.filter(record).flatMap(layer => Object.keys(layer)));
    const entries = [];
    for (const key of keys) {
      const fieldPath = [...path, key];
      const values = layers.map(layer => record(layer) && Object.hasOwn(layer, key) ? layer[key] : undefined)
        .filter(value => value !== undefined && !(value === null && inheritNull.has(JSON.stringify(fieldPath))));
      if (!values.length) continue;
      const selected = values.at(-1);
      // An explicit null resets the lower object before subsequent object overrides.
      const lastNull = values.lastIndexOf(null);
      const value = record(selected) ? merge(values.slice(lastNull + 1), fieldPath) : clone(selected);
      entries.push([key, value]);
    }
    return Object.fromEntries(entries);
  }
  return merge([defaults, workspace, request], []);
}
